with eligible as (select s.* from departments s where exists (select 1 from employees x where x.dept_id = s.id and x.manager_id in (13, 18, 23))) select case when budget >= 3593000 then 'LARGE' else 'SMALL' end as budget_tier, location, sum(case when dept_name = 'Sales' then budget else 0 end) as sales_budget, stddev_samp(budget) as budget_stddev, sort_array(collect_set(location)) as location_list from eligible group by 1, 2 having stddev_samp(budget) > 0 order by location desc
